ON INNODB_TABLES.TABLE_ID=INNODB_INDEXES.TABLE_ID WHERE INNODB_TABLES.NAME like "%test%";
+----------+---------+-----------------+
| TABLE_ID | NAME    | MERGE_THRESHOLD |
